// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;

    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(address manager, bool doPause) public {
        vm.assume(manager != address(0));

        bool ok;
        try c.paused() returns (bool p) {
            ok = p;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
